for (const item of items) {
  const { position, candidate_name, claimed_skills, past_company_type } = item.json;

  item.json.llm_prompt = `
Kamu adalah Senior Technical Interviewer untuk posisi ${position || "Software Engineer"}.
Tugasmu memvalidasi kedalaman teknikal kandidat bernama ${candidate_name}.

KONTEKS:
- Skill yang diklaim : ${claimed_skills}
- Latar belakang     : ${past_company_type}

TUGAS:
Buat 5 pertanyaan teknikal tingkat lanjut (studi kasus) untuk membuktikan apakah kandidat benar-benar paham atau hanya tahu permukaan. Fokus pada troubleshooting nyata dan trade-off arsitektur.

FORMAT OUTPUT (maks 900 karakter total):
1. [Topik]
   Pertanyaan: ...
   Ekspektasi Senior: ...

Gunakan Bahasa Indonesia. Langsung ke isi, tanpa pembuka.
  `.trim();
}

return items;

const aiQuestion = items[0].json.text; 


const candidateName = $('Loop Over Items').item.json.candidate_name;

let mockAnswer = "";

if (candidateName.includes("Budi")) {
  mockAnswer = "Untuk masalah CrashLoopBackOff, saya akan cek logs pod pakai kubectl logs, lalu describe pod untuk lihat events. Biasanya karena configmap salah atau app panic saat startup.";
} else {
  mockAnswer = "Saya biasanya restart servernya pak. Kalau masih error saya install ulang Kubernetesnya.";
}

return [
  {
    json: {
      question: aiQuestion,
      candidate_answer: mockAnswer,
      candidate_name: candidateName
    }
  }
];

const data = items[0].json;

const prompt = `
ROLE: You are a Senior Hiring Manager.
TASK: Evaluate the candidate's answer based on the technical question provided.

DATA:
- Candidate Name: ${data.candidate_name}
- Question Given: "${data.question.substring(0, 200)}..." (Truncated for brevity)
- Candidate Answer: "${data.candidate_answer}"

INSTRUCTION:
Give a score (0-100) and a brief critique.
- If the answer shows deep troubleshooting steps (logs, events, root cause), give HIGH score.
- If the answer is generic (restart server, reinstall), give LOW score (Red Flag).

OUTPUT FORMAT (Indonesian):
**Penilaian untuk ${data.candidate_name}**
--------------------------
🎯 **Skor:** [0-100]
💡 **Analisa:** [Penjelasan singkat 1 kalimat]
🚫 **Keputusan:** [LOLOS / GAGAL]
`;

return [
  {
    json: {
      eval_prompt: prompt
    }
  }
];
